import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import api from "../utils/api";

const AccountDashboard = () => {
  const [accounts, setAccounts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const loadAccounts = async () => {
      try {
        const token = localStorage.getItem("token");

        console.log("JWT token exists:", !!token);

        const response = await api.get("/api/accounts");

        console.log("Accounts API response:", response);
        console.log("Accounts:", response.data);

        setAccounts(response.data || []);
      } catch (err) {
        console.error("ERROR LOADING ACCOUNTS:", err);
        console.error("Status:", err.response?.status);
        console.error("Response:", err.response?.data);

        if (err.response?.status === 401) {
          setError(
            "401 - Unauthorized. Your JWT token is missing or invalid."
          );
        } else if (err.response?.status === 403) {
          setError(
            "403 - Access denied. Your account does not have ADMIN permission."
          );
        } else if (err.response?.status === 404) {
          setError("404 - Account API endpoint was not found.");
        } else if (err.response?.status === 500) {
          setError("500 - Backend error while loading accounts.");
        } else {
          setError(
            err.response?.data?.message ||
              err.message ||
              "Unable to load account details."
          );
        }
      } finally {
        setLoading(false);
      }
    };

    loadAccounts();
  }, []);

  if (loading) {
    return (
      <div className="dashboard-container">
        <h2>Account Dashboard</h2>
        <p>Loading account details...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="dashboard-container">
        <h2>Account Dashboard</h2>

        <p style={{ color: "red" }}>{error}</p>

        <p>
          Open Developer Tools with <strong>Ctrl + Shift + I</strong> to see
          the detailed error.
        </p>
      </div>
    );
  }

  return (
    <div className="dashboard-container">
      <h1>Account Dashboard</h1>

      {accounts.length === 0 ? (
        <div>
          <p>No accounts found.</p>
        </div>
      ) : (
        <div className="account-list">
          {accounts.map((account) => (
            <div
              className="account-card"
              key={account.accountId || account.accountNumber}
            >
              <h2>Account Details</h2>

              <p>
                <strong>Account Number:</strong>{" "}
                {account.accountNumber}
              </p>

              <p>
                <strong>Account Holder:</strong>{" "}
                {account.accountHolderName || "N/A"}
              </p>

              <p>
                <strong>Balance:</strong>{" "}
                ₹{Number(account.balance || 0).toFixed(2)}
              </p>

              <p>
                <strong>Account Type:</strong>{" "}
                {account.accountType || "N/A"}
              </p>

              <div className="dashboard-actions">

                <Link to={`/accounts/${account.accountId}`}>
                  Account Details
                </Link>

                <Link to={`/accounts/${account.accountId}/deposit`}>
                  Deposit
                </Link>

                <Link to={`/accounts/${account.accountId}/withdraw`}>
                  Withdraw
                </Link>

                <Link to={`/accounts/${account.accountId}/transfer`}>
                  Transfer
                </Link>

                <Link to={`/accounts/${account.accountId}/transactions`}>
                  Transaction History
                </Link>

              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AccountDashboard;
